#include <stdio.h>
#include <stddef.h>
int sum_range(const int *values, size_t count) {
    int total = 0;
    const int *current = values;
    for (size_t i = 0; i < count; ++i) {
        total += *current;
        ++current;
    }
    return total;
}
int main(void) {
    int values[] = {2, 4, 6};
    printf("%zu %d\n", sizeof values / sizeof values[0], sum_range(values, 3));
    return 0;
}

#include <stdio.h>
#include <stddef.h>
void rotate_left(int *values, size_t count) {
    if (count < 2) return;
    int first = values[0];
    for (size_t i = 1; i < count; ++i) values[i - 1] = values[i];
    values[count - 1] = first;
}
int main(void) {
    int values[] = {4, 7, 2};
    rotate_left(values, 3);
    printf("%d %d %d\n", values[0], values[1], values[2]);
    return 0;
}

