#include <stdio.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>
/* Parse one base-10 integer, permitting surrounding whitespace. */
int parse_integer(const char text[], long low, long high, long *result) {
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || errno == ERANGE) return 0;
    while (isspace((unsigned char)*end)) ++end;
    if (*end != '\0' || value < low || value > high) return 0;
    *result = value;
    return 1;
}
int main(void) {
    long value = 99;
    int ok = parse_integer("42x", -100, 100, &value);
    printf("%d %ld\n", ok, value);
    ok = parse_integer(" 0 ", -100, 100, &value);
    printf("%d %ld\n", ok, value);
    return 0;
}

#include <stdio.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>
/* Complete-line reader: 1 = line, 0 = EOF, -1 = too long, -2 = stream error.
   Call with an actual buffer and capacity between 2 and 64. */
int read_line(char buffer[], size_t capacity) {
    if (fgets(buffer, (int)capacity, stdin) == NULL)
        return ferror(stdin) ? -2 : 0;
    char *newline = strchr(buffer, '\n');
    if (newline != NULL) {
        *newline = '\0';
        return 1;
    }
    int next = fgetc(stdin);
    if (next == EOF) return ferror(stdin) ? -2 : 1;
    if (next == '\n') return 1;
    while (next != '\n' && next != EOF) next = fgetc(stdin);
    return ferror(stdin) ? -2 : -1;
}
/* Parse one base-10 integer, permitting surrounding whitespace. */
int parse_integer(const char text[], long low, long high, long *result) {
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || errno == ERANGE) return 0;
    while (isspace((unsigned char)*end)) ++end;
    if (*end != '\0' || value < low || value > high) return 0;
    *result = value;
    return 1;
}
int main(void) {
    char line[8];
    int status = read_line(line, sizeof line);
    if (status != 1) {
        puts(status == 0 ? "eof" : status == -2 ? "input error" : "too long");
        return 0;
    }
    long value;
    if (!parse_integer(line, 0, 130, &value)) puts("invalid");
    else printf("age=%ld\n", value);
    return 0;
}

