#include <ctype.h>
#include <limits.h>
/* Complete-line reader: 1 = line, 0 = EOF, -1 = too long, -2 = stream error.
   Call with an actual buffer and capacity between 2 and 64. */
int read_line(char buffer[], size_t capacity) {
    if (fgets(buffer, (int)capacity, stdin) == NULL)
        return ferror(stdin) ? -2 : 0;
    char *newline = strchr(buffer, '\n');
    if (newline != NULL) {
        *newline = '\0';
        return 1;
    }
    int next = fgetc(stdin);
    if (next == EOF) return ferror(stdin) ? -2 : 1;
    if (next == '\n') return 1;
    while (next != '\n' && next != EOF) next = fgetc(stdin);
    return ferror(stdin) ? -2 : -1;
}
/* Parse one base-10 integer, permitting surrounding whitespace. */
int parse_integer(const char text[], long low, long high, long *result) {
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || errno == ERANGE) return 0;
    while (isspace((unsigned char)*end)) ++end;
    if (*end != '\0' || value < low || value > high) return 0;
    *result = value;
    return 1;
}
int main(void) {
    char line[16];
    long quantity, price;
    if (read_line(line, sizeof line) != 1 || !parse_integer(line, 0, 1000, &quantity)) {
        puts("invalid"); return 0;
    }
    if (read_line(line, sizeof line) != 1 || !parse_integer(line, 0, 10000, &price)) {
        puts("invalid"); return 0;
    }
    printf("cents=%ld\n", quantity * price);
    return 0;
}

