solution.main.c:
#include <stddef.h>
int copy_bounded(char dst[], size_t capacity, const char src[]) {
    if (capacity == 0) return 0;
    size_t i = 0;
    while (i < capacity - 1 && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return src[i] == '\0';
}

