solution.main.c:
#include <stddef.h>
#include <string.h>
int append_bounded(char dst[], size_t capacity, const char suffix[]) {
    size_t used = strlen(dst);
    size_t extra = strlen(suffix);
    if (extra >= capacity - used) return 0;
    for (size_t i = 0; i <= extra; ++i) dst[used + i] = suffix[i];
    return 1;
}

