solution.main.c:
#include <stdlib.h>
#include <stdint.h>
typedef struct { int *data; size_t length, capacity; } IntVec;
int push(IntVec *v, int value) { if(v->length==v->capacity) { size_t next; if(v->capacity==0) next=4; else {if(v->capacity>SIZE_MAX/2) return 0; next=v->capacity*2;} if(next>SIZE_MAX/sizeof *v->data) return 0; int *p=realloc(v->data,next*sizeof *v->data); if(!p)return 0; v->data=p; v->capacity=next; } v->data[v->length++]=value; return 1; }

