solution.main.c:
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
long load_total(const char *path) {
    FILE *f=fopen(path,"r");if(!f)return -1;
    char line[32];long total=0;size_t count=0;int ok=1;
    while(fgets(line,sizeof line,f)) {
        char *end;errno=0;long n=strtol(line,&end,10);
        if(end==line||errno==ERANGE||n<0||n>600||count==100){ok=0;break;}
        if(*end=='\n')++end;
        if(*end!='\0'){ok=0;break;}
        total+=n;++count;
    }
    if(ferror(f))ok=0;
    if(fclose(f)!=0)ok=0;
    return ok?total:-1;
}

