#include "tracker.h"
#include <stdio.h>
#include <string.h>
int main(int argc,char *argv[]) {
    if(argc==1){puts("usage: tracker FILE list | add MINUTES | done INDEX");return 0;}
    if(argc<3){fputs("usage: tracker FILE list | add MINUTES | done INDEX\n",stderr);return 1;}
    TaskVec tasks={NULL,0,0};
    if(!load_tasks(argv[1],&tasks)){fputs("load failed: inspect the file format\n",stderr);return 1;}
    int status=0;long number;
    if(strcmp(argv[2],"list")==0&&argc==3) {
        for(size_t i=0;i<tasks.length;++i)
            printf("%zu: %d %s\n",i,tasks.data[i].minutes,tasks.data[i].done?"done":"pending");
        printf("records: %zu\n",tasks.length);
    } else if(strcmp(argv[2],"add")==0&&argc==4) {
        if(!parse_number(argv[3],600,&number)||!push_task(&tasks,(Task){(int)number,0})) {fputs("invalid duration or allocation failure\n",stderr);status=1;}
        else if(!save_tasks(argv[1],&tasks)){fputs("save failed\n",stderr);status=1;}
        else puts("added");
    } else if(strcmp(argv[2],"done")==0&&argc==4) {
        if(!parse_number(argv[3],9999,&number)||(size_t)number>=tasks.length){fputs("invalid index\n",stderr);status=1;}
        else {tasks.data[(size_t)number].done=1;if(!save_tasks(argv[1],&tasks)){fputs("save failed\n",stderr);status=1;}else puts("done");}
    } else {fputs("unknown command or wrong argument count\n",stderr);status=1;}
    clear_tasks(&tasks);return status;
}

