#include <stdio.h>
int total3(int a, int b, int c) {
    return a + b + c;
}
int span3(int a, int b, int c) {
    int low = a, high = a;
    if (b < low) low = b;
    if (c < low) low = c;
    if (b > high) high = b;
    if (c > high) high = c;
    return high - low;
}
void print_summary(int a, int b, int c) {
    int total = total3(a, b, c);
    double mean = (double)total / 3.0;
    printf("total=%d mean=%.2f range=%d\n", total, mean, span3(a, b, c));
}
int main(void) {
    print_summary(12, 17, 9);
    return 0;
}

