#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stddef.h>
typedef struct { int minutes; int done; } Task;
static int bounded(const char *text,long max,long *out) {
    char *end;errno=0;long value=strtol(text,&end,10);
    if(end==text||errno==ERANGE||value<0||value>max)return 0;
    if(*end=='\n')++end;
    if(*end!='\0')return 0;
    *out=value;return 1;
}
int main(void) {
    Task tasks[8];size_t used=0;char line[80];
    while(fgets(line,sizeof line,stdin)) {
        size_t len=strlen(line);
        if(len==sizeof line-1 && line[len-1]!='\n') {
            int ch;while((ch=fgetc(stdin))!='\n'&&ch!=EOF){}
            puts("invalid: line too long");continue;
        }
        long value;
        if(strncmp(line,"add ",4)==0) {
            if(!bounded(line+4,600,&value))puts("invalid duration");
            else if(used==8)puts("full");
            else {tasks[used++]=(Task){(int)value,0};puts("added");}
        } else if(strncmp(line,"done ",5)==0) {
            if(!bounded(line+5,7,&value)||(size_t)value>=used)puts("invalid index");
            else {tasks[(size_t)value].done=1;puts("done");}
        } else if(strcmp(line,"list\n")==0||strcmp(line,"list")==0) {
            long total=0;
            for(size_t i=0;i<used;++i) {
                printf("%zu: %d %s\n",i,tasks[i].minutes,tasks[i].done?"done":"pending");
                if(tasks[i].done)total+=tasks[i].minutes;
            }
            printf("completed minutes: %ld\n",total);
        } else if(strcmp(line,"quit\n")==0||strcmp(line,"quit")==0)break;
        else puts("commands: add MINUTES, done INDEX, list, quit");
    }
    if(ferror(stdin)){fputs("input error\n",stderr);return 1;}
    return 0;
}

