    FILE *f=fopen(path,"w");if(!f)return 0;int ok=1;
    for(size_t i=0;i<v->length;++i)
        if(fprintf(f,"%d %d\n",v->data[i].minutes,v->data[i].done)<0){ok=0;break;}
    if(fclose(f)!=0)ok=0;
    return ok;
}
static int parse_line(char *line,Task *out) {
    char *end;errno=0;long minutes=strtol(line,&end,10);
    if(end==line||*end!=' '||errno==ERANGE||minutes<0||minutes>600)return 0;
    char *second=end+1;errno=0;long done=strtol(second,&end,10);
    if(end==second||errno==ERANGE||(done!=0&&done!=1))return 0;
    if(*end=='\n')++end;
    if(*end!='\0')return 0;
    *out=(Task){(int)minutes,(int)done};return 1;
}
int load_tasks(const char *path,TaskVec *v) {
    FILE *f=fopen(path,"r");
    if(!f) {if(errno==ENOENT){clear_tasks(v);return 1;}return 0;}
    TaskVec parsed={NULL,0,0};char line[64];int ok=1;
    while(fgets(line,sizeof line,f)) {
        size_t len=strlen(line);Task task;
        if((len==sizeof line-1&&line[len-1]!='\n')||!parse_line(line,&task)||!push_task(&parsed,task)) {ok=0;break;}
    }
    if(ferror(f))ok=0;
    if(fclose(f)!=0)ok=0;
    if(!ok){clear_tasks(&parsed);return 0;}
    clear_tasks(v);*v=parsed;return 1;
}

